              '9': { type: 'exact', points: ['D'], guidance: '1 mark. A cube of edge 4 cm: SA = 96 cm², V = 64 cm³, ratio = 1.5.' },
              '10': { type: 'exact', points: ['D'], guidance: '1 mark.' },
              '11': { type: 'exact', points: ['C'], guidance: '1 mark.' },
              '12': { type: 'exact', points: ['A'], guidance: '1 mark.' },
